// ═══════════════════════════════════════════════════════════════════════
// EYWA v3.32 — brands sync: handles INSERT (new) + UPDATE (changed)
// ═══════════════════════════════════════════════════════════════════════
// sync_op = 'insert' → POST /v1/pages with parent.data_source_id
// sync_op = 'update' → PATCH /v1/pages/{notion_id} (no parent)
// ═══════════════════════════════════════════════════════════════════════

const WORKSPACES = {
  vt_intelligence: {
    token: $env.NOTION_TOKEN_VT_INTELLIGENCE,
    brand_ds_id: $env.NOTION_DB_BRANDS_VT_INTELLIGENCE,
    prop_names: {
      display_name:     'Display Name',
      workspace:        'Workspace',
      website:          'Website',
      gsc_property:     'GSC Property',
    },
  },
  the_gifted_synapse: {
    token: $env.NOTION_TOKEN_THE_GIFTED_SYNAPSE,
    brand_ds_id: $env.NOTION_DB_BRANDS_THE_GIFTED_SYNAPSE,
    prop_names: {
      display_name:     'Fingerprint Display Name',
      workspace:        'Notion Workspace',
      website:          'Brand Web URL',
      gsc_property:     'GSC Property URL',
    },
  },
};

function mapStatus(s) {
  if (!s || s === '') return 'PENDING';
  const t = s.toString().trim().toLowerCase();
  if (t === 'active') return 'ACTIVE';
  if (t === 'inactive' || t === 'in_active' || t === 'in active') return 'IN ACTIVE';
  return 'PENDING';
}

function buildProperties(row, ws) {
  const config = WORKSPACES[ws];
  const N = config.prop_names;
  const props = {
    'Brand Name': { title: [{ text: { content: row.brand_name || '(unnamed)' } }] },
    'Brand Slug': { rich_text: [{ text: { content: row.brand_slug || '' } }] },
    'Fingerprint': { rich_text: [{ text: { content: row.fingerprint || '' } }] },
    [N.display_name]: { rich_text: [{ text: { content: row.fingerprint_display_name || '' } }] },
    'Status': { select: { name: mapStatus(row.status) } },
    'Brand Structure': { select: { name: row.brand_structure || 'monolithic' } },
    [N.workspace]: { select: { name: ws } },
  };
  if (row.company) props['Company'] = { rich_text: [{ text: { content: row.company } }] };
  if (row.brand_description) props['Brand Description'] = { rich_text: [{ text: { content: row.brand_description } }] };
  if (row.brand_web_url) props[N.website] = { url: row.brand_web_url };
  if (row.gsc_property_url) props[N.gsc_property] = { url: row.gsc_property_url };
  if (row.ga4_property_id) props['GA4 Property ID'] = { rich_text: [{ text: { content: row.ga4_property_id } }] };
  if (row.positioning_mode) props['Positioning Mode'] = { select: { name: row.positioning_mode } };
  if (row.compliance_profile) {
    const cp = typeof row.compliance_profile === 'string'
      ? row.compliance_profile
      : JSON.stringify(row.compliance_profile, null, 2);
    props['Compliance Profile'] = { rich_text: [{ text: { content: cp.substring(0, 2000) } }] };
  }
  return props;
}

const out = [];
const errors = [];

for (const item of $input.all()) {
  const row = item.json;
  const ws = row.notion_workspace;
  const config = WORKSPACES[ws];
  if (!config) {
    errors.push({ brand_slug: row.brand_slug, reason: `unsupported workspace: ${ws}` });
    continue;
  }
  if (!config.token) { errors.push({ brand_slug: row.brand_slug, reason: 'token missing' }); continue; }
  if (!config.brand_ds_id) { errors.push({ brand_slug: row.brand_slug, reason: 'ds_id missing' }); continue; }

  const isInsert = row.sync_op === 'insert';
  const dsId = config.brand_ds_id.replace('collection://', '');
  const properties = buildProperties(row, ws);

  const httpUrl = isInsert
    ? 'https://api.notion.com/v1/pages'
    : `https://api.notion.com/v1/pages/${row.notion_id}`;
  const httpMethod = isInsert ? 'POST' : 'PATCH';
  const payload = isInsert
    ? { parent: { type: 'data_source_id', data_source_id: dsId }, properties }
    : { properties };

  out.push({
    json: {
      _supabase_id: row.id,
      _brand_slug: row.brand_slug,
      _workspace: ws,
      _sync_op: row.sync_op,
      _existing_notion_id: row.notion_id || null,
      notion_token: config.token,
      http_url: httpUrl,
      http_method: httpMethod,
      payload,
    },
  });
}

if (errors.length) console.log('[S→N] validation errors:', JSON.stringify(errors));
return out;

// ═══════════════════════════════════════════════════════════════════════
// Parse Notion API response — recover upstream via paired items
// Works for both POST (insert) + PATCH (update) — both return page object
// ═══════════════════════════════════════════════════════════════════════

const out = [];
const inputs = $input.all();
const UPSTREAM = 'Code: resolve workspace + build per-ws payload';

for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i];
  const resp = item.json;
  const status = resp.statusCode;
  const body = resp.body;

  let upstream = {};
  try {
    const u = $(UPSTREAM).itemMatching(i);
    upstream = u ? u.json : {};
  } catch (e) {
    const arr = $items(UPSTREAM);
    upstream = arr[i] ? arr[i].json : {};
  }

  const supabaseId = upstream._supabase_id || null;
  const brandSlug = upstream._brand_slug || null;
  const workspace = upstream._workspace || null;
  const syncOp = upstream._sync_op || null;

  if (status >= 200 && status < 300 && body && body.id) {
    // Build UPDATE SQL directly (avoid n8n queryReplacement bug)
    const slugEsc = (brandSlug || '').replace(/'/g, "''");
    const idEsc = (body.id || '').replace(/'/g, "''");
    const updateSql = syncOp === 'insert'
      ? `UPDATE brands SET notion_id = '${idEsc}', notion_synced_at = NOW(), updated_at = NOW() WHERE brand_slug = '${slugEsc}' RETURNING brand_slug, notion_id, notion_synced_at::time AS synced_at;`
      : `UPDATE brands SET notion_synced_at = NOW() WHERE brand_slug = '${slugEsc}' RETURNING brand_slug, notion_id, notion_synced_at::time AS synced_at;`;
    out.push({
      json: {
        _supabase_id: supabaseId,
        _brand_slug: brandSlug,
        _workspace: workspace,
        _sync_op: syncOp,
        notion_id: body.id,
        _ok: true,
        update_sql: updateSql,
      },
    });
  } else {
    out.push({
      json: {
        _supabase_id: supabaseId,
        _brand_slug: brandSlug,
        _workspace: workspace,
        _sync_op: syncOp,
        _ok: false,
        _error: {
          status,
          notion_error_code: body && body.code || null,
          notion_error_message: body && body.message || 'unknown',
          notion_request_id: body && body.request_id || null,
        },
      },
    });
  }
}
return out;
